link:64796,
text:['"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"37gbl\",\"text\":\"\\\"You might hear the term Dual Diagnosis often because these conditions frequently show up together. We\'re talking about disorders like Depression, Anxiety, PTSD, and Bipolar Disorder frequently co-occurring with substance misuse. This is not a small issue; it affects many individuals worldwide. That\'s why integrated care is so important—it’s the essential approach to treating both disorders together and genuinely improving health outcomes.\\\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":444,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":444,\"style\":\"defaultTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":444,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":444,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":444,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":444,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":444,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":444,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":444,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":444,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":444,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":444,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":444,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":444,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":444,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":444,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":444,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":444,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":444,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":444,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":444,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":444,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":444,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":444,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":444,\"style\":\"desktop-fontSize:12\"},{\"offset\":0,\"length\":444,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":444,\"style\":\"textShadowColor:#19191929\"},{\"offset\":0,\"length\":444,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":444,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":444,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":444,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":444,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":444,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":444,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":444,\"style\":\"WebkitTextStrokeColor:#18a4bd\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}},{\"key\":\"fusjb\",\"text\":\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"\\\"You might hear the term Dual Diagnosis often because these conditions frequently show up together. We\'re talking about disorders like Depression, Anxiety, PTSD, and Bipolar Disorder frequently co-occurring with substance misuse. This is not a small issue; it affects many individuals worldwide. That\'s why integrated care is so important—it’s the essential approach to treating both disorders together and genuinely improving health outcomes.\\\"\\n\",\"duration\":32,\"end\":32,\"id\":\"caption__8306__5\",\"dirtyReasons\":[\"TEXT_MODIFIED\"],\"speechAgentV1\":{\"name\":\"Amelia - young and enthusiastic\",\"id\":\"ZF6FPAbjXT4488VcRRnw\",\"source\":\"ElevenLabs\"}}]"']
