link:68278,
text:['"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"3voen\",\"text\":\"\\\"Here\'s a concrete example : You have Anxious Thoughts about an upcoming social event, which triggers Anxiety (feeling). This overwhelming emotion can trigger Substance Use as a way to cope. The substance use then worsens your existing mental health symptoms—maybe the anxiety comes back worse later—and this intensifies the negative cycle. This is how a Repetitive Destructive Pattern forms: worsening symptoms reinforce coping through substance use.\\\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":452,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":452,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":452,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":452,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":452,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":452,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":452,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":452,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":452,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":452,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":452,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":452,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":452,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":452,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":452,\"style\":\"desktop-fontSize:12\"},{\"offset\":0,\"length\":452,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":452,\"style\":\"textShadowColor:#19191929\"},{\"offset\":0,\"length\":452,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":452,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":452,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":452,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":452,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":452,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":452,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":452,\"style\":\"WebkitTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":452,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":452,\"style\":\"defaultTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":452,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":452,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":452,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":452,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":452,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":452,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":452,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":452,\"style\":\"color:#ffffff\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}},{\"key\":\"4tdcv\",\"text\":\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"\\\"Here\'s a concrete example : You have Anxious Thoughts about an upcoming social event, which triggers Anxiety (feeling). This overwhelming emotion can trigger Substance Use as a way to cope. The substance use then worsens your existing mental health symptoms—maybe the anxiety comes back worse later—and this intensifies the negative cycle. This is how a Repetitive Destructive Pattern forms: worsening symptoms reinforce coping through substance use.\\\"\\n\",\"duration\":33.3,\"end\":33.3,\"id\":\"caption__6831__11\",\"dirtyReasons\":[\"TEXT_MODIFIED\"],\"speechAgentV1\":{\"name\":\"Amelia - young and enthusiastic\",\"id\":\"ZF6FPAbjXT4488VcRRnw\",\"source\":\"ElevenLabs\"}}]"']
