text:['"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"ctv1n\",\"text\":\"The Impact Substance Use has on Mental Health is worsening and the cycle is difficult to break.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":95,\"style\":\"tablet-fontSize:50\"},{\"offset\":0,\"length\":95,\"style\":\"textShadowColor:#19191929\"},{\"offset\":0,\"length\":95,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":95,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":95,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":95,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":95,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":95,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":95,\"style\":\"WebkitTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":95,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":95,\"style\":\"defaultTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":95,\"style\":\"color:#f2f6fa\"},{\"offset\":0,\"length\":95,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":95,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":95,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":95,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":95,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":95,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":95,\"style\":\"fontFamily:Dosis\"},{\"offset\":0,\"length\":95,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":95,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":95,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":95,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":95,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":95,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":95,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":95,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":95,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":95,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":95,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":95,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":95,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":95,\"style\":\"desktop-fontSize:12\"},{\"offset\":0,\"length\":95,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":95,\"style\":\"mobile-fontSize:40\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"left\",\"marginBottom\":\"0%\",\"presetId\":\"text-heading-1\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"The Impact Substance Use has on Mental Health is worsening and the cycle is difficult to break.\",\"duration\":5.4,\"end\":5.4,\"id\":\"caption__5853__50\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"Amelia - young and enthusiastic\",\"id\":\"ZF6FPAbjXT4488VcRRnw\",\"source\":\"ElevenLabs\"}}]"']
