link:44693,
text:['"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"fhqcc\",\"text\":\"All-or-Nothing Thinking (Black-and-White Thinking) : \\\"This is viewing things in extremes—either all good or all bad. If something isn’t perfect, you believe it’s a complete failure. A setback in recovery can feel like total defeat instead of just part of the process. For example: \'I missed one meeting this week, so I’ve completely failed my recovery\'.\\\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":354,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":354,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":354,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":354,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":354,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":354,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":354,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":354,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":354,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":354,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":354,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":354,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":354,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":354,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":354,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":354,\"style\":\"desktop-fontSize:12\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowColor:#19191929\"},{\"offset\":0,\"length\":354,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":354,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":354,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":354,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":354,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":354,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":354,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":354,\"style\":\"WebkitTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":354,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":354,\"style\":\"defaultTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":354,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":354,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":354,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":354,\"style\":\"textShadow:none\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}},{\"key\":\"4qu7f\",\"text\":\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"All-or-Nothing Thinking (Black-and-White Thinking) : \\\"This is viewing things in extremes—either all good or all bad. If something isn’t perfect, you believe it’s a complete failure. A setback in recovery can feel like total defeat instead of just part of the process. For example: \'I missed one meeting this week, so I’ve completely failed my recovery\'.\\\"\\n\",\"duration\":27.2,\"end\":27.2,\"id\":\"caption__1958__18\",\"dirtyReasons\":[\"TEXT_MODIFIED\"],\"speechAgentV1\":{\"name\":\"Amelia - young and enthusiastic\",\"id\":\"ZF6FPAbjXT4488VcRRnw\",\"source\":\"ElevenLabs\"}}]"']
