link:65562,
text:['"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"75cgb\",\"text\":\"\\\"Meet John, a 45-year-old manager diagnosed with Major Depressive Disorder and Alcohol Use Disorder. His core thought is, \'I\'m a failure, and I can\'t stand this feeling\'. His primary coping mechanism is drinking a six-pack alone every evening, which he believes \'numbs the pain\'. But this just makes the depression worse the next day, fueling the cycle. Your task is to identify the behavior that most likely reinforces his depression  and select the appropriate initial Cognitive Behavioral Therapy technique.\\\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":511,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":511,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":511,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":511,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":511,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":511,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":511,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":511,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":511,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":511,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":511,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":511,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":511,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":511,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":511,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":511,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":511,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":511,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":511,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":511,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":511,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":511,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":511,\"style\":\"desktop-fontSize:12\"},{\"offset\":0,\"length\":511,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":511,\"style\":\"textShadowColor:#19191929\"},{\"offset\":0,\"length\":511,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":511,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":511,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":511,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":511,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":511,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":511,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":511,\"style\":\"WebkitTextStrokeColor:#18a4bd\"},{\"offset\":0,\"length\":511,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":511,\"style\":\"defaultTextStrokeColor:#18a4bd\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}},{\"key\":\"4r44m\",\"text\":\"\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"verticalAlignMarginBottom\":\"0px\",\"listIndent\":\"100%\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"verticalAlignMarginTop\":\"auto\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"\\\"Meet John, a 45-year-old manager diagnosed with Major Depressive Disorder and Alcohol Use Disorder. His core thought is, \'I\'m a failure, and I can\'t stand this feeling\'. His primary coping mechanism is drinking a six-pack alone every evening, which he believes \'numbs the pain\'. But this just makes the depression worse the next day, fueling the cycle. Your task is to identify the behavior that most likely reinforces his depression  and select the appropriate initial Cognitive Behavioral Therapy technique.\\\"\\n\",\"duration\":34.7,\"end\":34.7,\"id\":\"caption__7238__38\",\"dirtyReasons\":[\"TEXT_MODIFIED\"],\"speechAgentV1\":{\"name\":\"Amelia - young and enthusiastic\",\"id\":\"ZF6FPAbjXT4488VcRRnw\",\"source\":\"ElevenLabs\"}}]"']
